"""Original Go fixtures with independently stated selected-closure expectations."""
CASES = []


def case(identity, declarations, *, code=None, status=None, closure=None, typecheck_only=None, language="go1.25"):
    row = {"id": identity, "source": "package policy\n"+declarations+"\n", "root": "Root", "language": language,
           "expected_status": status or ("rejected_candidate" if code else "candidate_unproved")}
    if code: row["expected_code"] = code
    if closure is not None: row["expected_closure"] = closure
    if typecheck_only is not None: row["expected_typecheck_only"] = typecheck_only
    CASES.append(row)


